#!/usr/bin/env bash
# СУДИТ: scripts/signal-precision-corpus.py
# probe_D1152 — реестр носителей засчитывается, только когда связан с опознанием класса: форма из списка
# REGISTRY_FORMS прибора (число рядом со словом «носители» или «места», раздел «Братья корня») в 300 знаках от опознания. Ход «тот же класс» + далёкий «33 из 33» тестов, номер пункта, счёт
# повторов — долг; «носителей 3 из 7» рядом с опознанием — реестр (положительный контроль). Ответ владельца судится
# кодом ВМЕСТЕ с текстом: упавший разбор тоже выходит с 1, и без текста ноги «долг» зеленели бы на падении.
# Красная (1), пока владелец признака засчитывает чужое число; 2 — владельца нет.
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
C="$R/scripts/signal-precision-corpus.py"
[ -f "$C" ] || exit 2
ask() {   # 0 — реестр назван, 1 — долг, иначе «x<код>»: ответа нет
    local out rc
    out=$(printf '%s' "$1" | python3 "$C" --registry-in-text 2>/dev/null); rc=$?
    case "$rc:$out" in
        0:*'реестр назван: да'*) echo 0 ;;
        1:*'реестр назван: НЕТ'*) echo 1 ;;
        *) echo "x$rc" ;;
    esac
}
far=$(printf 'Правка прошла, тесты зелёные. %.0s' $(seq 12))
bad=0
# Окно судится счётом НОСИТЕЛЕЙ вдали, а не счётом тестов: «33 из 33» отбивает и регулярка без всякого окна (второй
# круг, M2). Опознание в конце длинного текста — место ищется, а не берётся началом; 300 и 301 — ширина окна.
[ "$(ask "Это тот же класс, что вчера. ${far} Где-то ещё носителей 3 из 7.")" = 1 ] || { echo "далёкий счёт носителей засчитан реестром"; bad=1; }
[ "$(ask "Где-то носителей 3 из 7. ${far} Это тот же класс, что вчера.")" = 1 ] || { echo "далёкий счёт носителей ДО опознания засчитан реестром"; bad=1; }
[ "$(ask "${far} Это тот же класс: носителей 3 из 7.")" = 0 ] || { echo "реестр рядом с опознанием в конце текста не засчитан"; bad=1; }
[ "$(ask 'Носителей 3 из 7: это тот же класс, что вчера.')" = 0 ] || { echo "реестр перед опознанием не засчитан"; bad=1; }
[ "$(ask "Тот же класс.$(printf '%*s' 287 '')носителей 3 из 7.")" = 0 ] || { echo "реестр на 300 знаков не засчитан"; bad=1; }
[ "$(ask "Тот же класс.$(printf '%*s' 288 '')носителей 3 из 7.")" = 1 ] || { echo "реестр на 301 знак засчитан"; bad=1; }
[ "$(ask 'Это тот же класс, что D420.')" = 1 ] || { echo "номер пункта засчитан реестром"; bad=1; }
[ "$(ask 'Тот же класс. Носителей не считал (D1200).')" = 1 ] || { echo "номер пункта при слове о носителях засчитан реестром"; bad=1; }
[ "$(ask 'Тот же класс. Все три теста зелёные.')" = 1 ] || { echo "счёт тестов засчитан реестром"; bad=1; }
[ "$(ask 'Тот же класс, что сегодня трижды.')" = 1 ] || { echo "счёт повторов засчитан реестром"; bad=1; }
[ "$(ask 'Тот же класс: носителей 3 из 7.')" = 0 ] || { echo "реестр рядом с опознанием не засчитан"; bad=1; }
exit "$bad"
